13	/// <summary>
14	/// Class for accessing the list of collections in a SQLite vector store.
15	/// </summary>
16	/// <remarks>
17	/// This class can be used with collections of any schema type, but requires you to provide schema information when getting a collection.
18	/// </remarks>
19	public class SqliteVectorStore : IVectorStore
20	{
21	    /// <summary><see cref="DbConnection"/> that will be used to manage the data in SQLite.</summary>
22	    private readonly DbConnection _connection;
23	
24	    /// <summary>Optional configuration options for this class.</summary>
25	    private readonly SqliteVectorStoreOptions _options;
26	
27	    /// <summary>
28	    /// Initializes a new instance of the <see cref="SqliteVectorStore"/> class.
29	    /// </summary>
30	    /// <param name="connection"><see cref="SqliteConnection"/> that will be used to manage the data in SQLite.</param>
31	    /// <param name="options">Optional configuration options for this class.</param>
32	    public SqliteVectorStore(
33	        DbConnection connection,
34	        SqliteVectorStoreOptions? options = default)
35	    {
36	        Verify.NotNull(connection);
37	
38	        this._connection = connection;
39	        this._options = options ?? new();
40	    }
41	
42	    /// <inheritdoc />
43	    public virtual IVectorStoreRecordCollection<TKey, TRecord> GetCollection<TKey, TRecord>(string name, VectorStoreRecordDefinition? vectorStoreRecordDefinition = null)
44	        where TKey : notnull
45	    {
46	#pragma warning disable CS0618 // ISqliteVectorStoreRecordCollectionFactory is obsolete
47	        if (this._options.VectorStoreCollectionFactory is not null)
48	        {
49	            return this._options.VectorStoreCollectionFactory.CreateVectorStoreRecordCollection<TKey, TRecord>(
50	                this._connection,
51	                name,
52	                vectorStoreRecordDefinition);
53	        }
54	#pragma warning restore CS0618
55	
56	        if (typeof(TKey) != typeof(string) && typeof(TKey) != typeof(ulong))
57	        {
58	            throw new NotSupportedException($"Only {nameof(String)} and {nameof(UInt64)} keys are supported.");
59	        }
60	
61	        var recordCollection = new SqliteVectorStoreRecordCollection<TRecord>(
62	            this._connection,
63	            name,
64	            new()
65	            {
66	                VectorStoreRecordDefinition = vectorStoreRecordDefinition,
67	                VectorSearchExtensionName = this._options.VectorSearchExtensionName,
68	                VectorVirtualTableName = this._options.VectorVirtualTableName
69	            }) as IVectorStoreRecordCollection<TKey, TRecord>;
70	
71	        return recordCollection!;
72	    }
73	
74	    /// <inheritdoc />
75	    public virtual async IAsyncEnumerable<string> ListCollectionNamesAsync([EnumeratorCancellation] CancellationToken cancellationToken = default)
76	    {
77	        const string TablePropertyName = "name";
78	        const string Query = $"SELECT {TablePropertyName} FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';";
79	
80	        using var command = this._connection.CreateCommand();
81	
82	        command.CommandText = Query;
83	
84	        using var reader = await command.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false);
85	
86	        while (await reader.ReadAsync(cancellationToken).ConfigureAwait(false))
87	        {
88	            var ordinal = reader.GetOrdinal(TablePropertyName);
89	            yield return reader.GetString(ordinal);
90	        }
91	    }
92	}
